-- Maake Enterprise initial schema. Seeded catalogue is illustrative only.
create extension if not exists pgcrypto;
create table public.business_profile (id boolean primary key default true check(id=true),business_name text not null default 'Maake Enterprise',tagline text not null default 'Food. Transport. Events. Solutions.',service_area text not null default 'Maphalle and surrounding areas',contact_phone text,whatsapp_number text,contact_email text,hours_note text not null default 'Operating hours to be confirmed',is_demo boolean not null default true,updated_at timestamptz not null default now());
create table public.products (id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,description text not null default '',category text not null default 'meals',price numeric(10,2) not null check(price>=0),image_url text,is_available boolean not null default true,is_published boolean not null default false,is_demo boolean not null default true,sort_order int not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.services (id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,description text not null default '',category text not null check(category in ('catering','event_equipment','sanitation','cold_storage','entertainment')),image_url text,enquiry_only boolean not null default true,is_active boolean not null default true,sort_order int not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.business_hours (id uuid primary key default gen_random_uuid(),day_of_week smallint unique not null check(day_of_week between 0 and 6),opens_at time,closes_at time,is_closed boolean not null default false,note text,check(is_closed or (opens_at is not null and closes_at is not null)));
create table public.transport_routes (id uuid primary key default gen_random_uuid(),route_name text not null,origin text not null,destination text not null,operating_days text[] not null default '{}',departure_times text[] not null default '{}',fare numeric(10,2) check(fare is null or fare>=0),notes text,is_active boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.orders (id uuid primary key default gen_random_uuid(),order_number text unique not null,customer_name text not null,customer_phone text not null,fulfilment_method text not null check(fulfilment_method in ('collection','delivery')),delivery_address text,customer_notes text,status text not null default 'pending' check(status in ('pending','accepted','preparing','ready','completed','cancelled')),payment_status text not null default 'unpaid' check(payment_status in ('unpaid','awaiting_confirmation','paid','refunded')),subtotal numeric(10,2) not null check(subtotal>=0),delivery_fee numeric(10,2) not null default 0 check(delivery_fee>=0),total numeric(10,2) not null check(total>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(fulfilment_method<>'delivery' or nullif(trim(delivery_address),'') is not null));
create table public.order_items (id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid references public.products(id) on delete set null,product_name text not null,unit_price numeric(10,2) not null,quantity int not null check(quantity between 1 and 30),line_total numeric(10,2) not null,created_at timestamptz not null default now());
create table public.service_enquiries (id uuid primary key default gen_random_uuid(),service_id uuid references public.services(id) on delete set null,service_name text not null,customer_name text not null,customer_phone text not null,customer_email text,requested_date date,event_location text,guest_count int,details text,status text not null default 'new' check(status in ('new','reviewing','quoted','confirmed','completed','declined')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.transport_enquiries (id uuid primary key default gen_random_uuid(),transport_type text not null check(transport_type in ('scheduled_route','private_hire')),route_id uuid references public.transport_routes(id) on delete set null,customer_name text not null,customer_phone text not null,pickup_location text not null,destination text not null,travel_date date,preferred_time text,passenger_count int not null default 1 check(passenger_count between 1 and 100),details text,status text not null default 'new' check(status in ('new','reviewing','quoted','confirmed','completed','declined')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index products_listing_idx on public.products(is_published,is_available,sort_order); create index orders_status_created_idx on public.orders(status,created_at desc); create index order_items_order_idx on public.order_items(order_id); create index service_enquiries_status_idx on public.service_enquiries(status,created_at desc); create index transport_enquiries_status_idx on public.transport_enquiries(status,created_at desc);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['business_profile','products','services','business_hours','transport_routes','orders','order_items','service_enquiries','transport_enquiries'] LOOP EXECUTE format('alter table public.%I enable row level security',t); END LOOP; END $$;
create policy business_profile_public_read on public.business_profile for select to anon,authenticated using(id=true); create policy business_profile_admin on public.business_profile for all to authenticated using((select auth.jwt()->'app_metadata'->>'role')='maake_admin') with check((select auth.jwt()->'app_metadata'->>'role')='maake_admin');
create policy products_public_read on public.products for select to anon,authenticated using(is_published and is_available); create policy products_admin on public.products for all to authenticated using((select auth.jwt()->'app_metadata'->>'role')='maake_admin') with check((select auth.jwt()->'app_metadata'->>'role')='maake_admin');
create policy services_public_read on public.services for select to anon,authenticated using(is_active); create policy services_admin on public.services for all to authenticated using((select auth.jwt()->'app_metadata'->>'role')='maake_admin') with check((select auth.jwt()->'app_metadata'->>'role')='maake_admin');
create policy hours_public_read on public.business_hours for select to anon,authenticated using(true); create policy hours_admin on public.business_hours for all to authenticated using((select auth.jwt()->'app_metadata'->>'role')='maake_admin') with check((select auth.jwt()->'app_metadata'->>'role')='maake_admin');
create policy routes_public_read on public.transport_routes for select to anon,authenticated using(is_active); create policy routes_admin on public.transport_routes for all to authenticated using((select auth.jwt()->'app_metadata'->>'role')='maake_admin') with check((select auth.jwt()->'app_metadata'->>'role')='maake_admin');
create policy orders_admin on public.orders for all to authenticated using((select auth.jwt()->'app_metadata'->>'role')='maake_admin') with check((select auth.jwt()->'app_metadata'->>'role')='maake_admin'); create policy items_admin on public.order_items for all to authenticated using((select auth.jwt()->'app_metadata'->>'role')='maake_admin') with check((select auth.jwt()->'app_metadata'->>'role')='maake_admin');
create policy service_enquiry_public_insert on public.service_enquiries for insert to anon,authenticated with check(status='new' and length(trim(customer_name)) between 2 and 100 and length(trim(customer_phone)) between 7 and 30); create policy service_enquiry_admin on public.service_enquiries for all to authenticated using((select auth.jwt()->'app_metadata'->>'role')='maake_admin') with check((select auth.jwt()->'app_metadata'->>'role')='maake_admin');
create policy transport_enquiry_public_insert on public.transport_enquiries for insert to anon,authenticated with check(status='new' and length(trim(customer_name)) between 2 and 100 and length(trim(customer_phone)) between 7 and 30); create policy transport_enquiry_admin on public.transport_enquiries for all to authenticated using((select auth.jwt()->'app_metadata'->>'role')='maake_admin') with check((select auth.jwt()->'app_metadata'->>'role')='maake_admin');
grant select on public.business_profile,public.products,public.services,public.business_hours,public.transport_routes to anon,authenticated; grant select,insert,update,delete on public.business_profile,public.products,public.services,public.business_hours,public.transport_routes to authenticated; grant select,update on public.orders,public.order_items,public.service_enquiries,public.transport_enquiries to authenticated; grant insert on public.service_enquiries,public.transport_enquiries to anon,authenticated;
create or replace function public.submit_maake_order(p_customer_name text,p_customer_phone text,p_fulfilment_method text,p_delivery_address text,p_customer_notes text,p_items jsonb) returns uuid language plpgsql security definer set search_path='' as $$ declare v_id uuid:=pg_catalog.gen_random_uuid(); v_number text; v_subtotal numeric(10,2):=0; v_item jsonb; v_pid uuid; v_name text; v_price numeric(10,2); v_qty int; begin
if p_customer_name is null or length(trim(p_customer_name)) not between 2 and 100 then raise exception 'Enter a valid name'; end if; if p_customer_phone is null or length(trim(p_customer_phone)) not between 7 and 30 then raise exception 'Enter a valid phone number'; end if; if p_fulfilment_method not in ('collection','delivery') then raise exception 'Invalid fulfilment method'; end if; if p_fulfilment_method='delivery' and nullif(trim(p_delivery_address),'') is null then raise exception 'Delivery address required'; end if; if p_items is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items) not between 1 and 30 then raise exception 'Basket is empty or too large'; end if;
v_number:='ME-'||upper(substr(replace(v_id::text,'-',''),1,8)); insert into public.orders(id,order_number,customer_name,customer_phone,fulfilment_method,delivery_address,customer_notes,subtotal,total) values(v_id,v_number,trim(p_customer_name),trim(p_customer_phone),p_fulfilment_method,case when p_fulfilment_method='delivery' then trim(p_delivery_address) end,left(coalesce(p_customer_notes,''),1000),0,0);
for v_item in select value from jsonb_array_elements(p_items) loop v_pid:=(v_item->>'product_id')::uuid; v_qty:=(v_item->>'quantity')::int; if v_qty not between 1 and 30 then raise exception 'Invalid quantity'; end if; select id,name,price into v_pid,v_name,v_price from public.products where id=v_pid and is_published and is_available; if not found then raise exception 'A product is unavailable'; end if; v_subtotal:=v_subtotal+v_price*v_qty; insert into public.order_items(order_id,product_id,product_name,unit_price,quantity,line_total) values(v_id,v_pid,v_name,v_price,v_qty,v_price*v_qty); end loop; update public.orders set subtotal=v_subtotal,total=v_subtotal,updated_at=now() where id=v_id; return v_id; end; $$;
revoke all on function public.submit_maake_order(text,text,text,text,text,jsonb) from public; grant execute on function public.submit_maake_order(text,text,text,text,text,jsonb) to anon,authenticated;
insert into public.business_profile(id) values(true) on conflict(id) do nothing;
